function App() {
  const [screen, setScreen] = useState<'intro' | 'login' | 'public' | 'authority'>('intro');
  const [eventTick, setEventTick] = useState(0);
  const [realtimeConnected, setRealtimeConnected] = useState(false);
  const [auth, setAuth] = useState(!!localStorage.getItem('pralay_token'));

  useEffect(() => {
    const es = new EventSource(eventsUrl);
    const bump = () => setEventTick(v => v + 1);
    es.onopen = () => setRealtimeConnected(true);
    es.onerror = () => setRealtimeConnected(false);
    ['incident.created', 'incident.updated', 'complaint.created', 'complaint.updated', 'risk.updated', 'alert.created', 'alert.updated', 'resource.dispatched', 'resource.updated', 'evacuation.created', 'evacuation.updated', 'route.created', 'simulation.reset'].forEach(e => es.addEventListener(e, bump));
    return () => es.close();
  }, []);

  if (screen === 'intro') return <Intro onPublic={() => setScreen('public')} onLogin={() => setScreen('login')} />;
  if (screen === 'login') return <Login onBack={() => setScreen('intro')} onSuccess={() => { setAuth(true); setScreen('authority'); }} />;
  if (screen === 'authority' && auth) return <Authority tick={eventTick} realtimeConnected={realtimeConnected} onLogout={() => { localStorage.removeItem('pralay_token'); setAuth(false); setScreen('intro'); }} />;
  return <PublicSafety tick={eventTick} realtimeConnected={realtimeConnected} onAuthority={() => setScreen(auth ? 'authority' : 'login')} onHome={() => setScreen('intro')} />;
}

