    {complaintOpen && <ComplaintModal onClose={() => setComplaintOpen(false)} />}
    {aiOpen && <PublicAIChat state={location.includes(',') ? location.split(',')[1].trim() : 'ALL INDIA'} onClose={() => setAiOpen(false)} />}
